import {
  AuthlessApiError,
  createAuthlessApiClient,
} from "@authless/api-client";

const client = createAuthlessApiClient({
  appCredentialToken: process.env.AUTHLESS_APP_CREDENTIAL!,
  baseUrl: "https://api.authle.ss",
  retry: { maxAttempts: 2 },
});
const scope = {
  workspaceId: process.env.AUTHLESS_TEST_WORKSPACE_ID!,
  appId: process.env.AUTHLESS_TEST_APP_ID!,
};
const correlationId = crypto.randomUUID();
const customerReference = `rest-guide-${crypto.randomUUID()}`;

try {
  // Durable idempotency: reuse this key only for this exact invitation claim.
  await client.appMemberships.invite({
    ...scope,
    correlationId,
    idempotencyKey: crypto.randomUUID(),
    confirmed: true,
    customerReference,
    email: "rest-guide-user@example.test",
  });

  // Invitations are enumeration-safe, so locate the created test record by
  // its caller-owned reference, then preserve the opaque continuation cursor.
  const first = await client.appMemberships.list({
    ...scope, correlationId, query: customerReference, limit: 1,
  });
  const membership = first.memberships[0];
  if (!membership) throw new Error("created_test_membership_not_visible");
  if (first.nextCursor) {
    await client.appMemberships.list({
      ...scope, correlationId, cursor: first.nextCursor, limit: 1,
    });
  }

  const current = await client.appMemberships.get({
    ...scope, correlationId, membershipId: membership.id,
  });

  // The client sends If-Match: "<version>" and keeps this mutation's
  // idempotency key unchanged across only its classified-safe retries.
  await client.appMemberships.changeStatus({
    ...scope,
    correlationId,
    membershipId: current.id,
    expectedVersion: current.version,
    idempotencyKey: crypto.randomUUID(),
    action: "revoke",
    confirmed: true,
    reason: "access_ended",
  });
  console.info("REST_GUIDE_COMPLETE cleanup_ok", { correlationId });
} catch (error) {
  if (error instanceof AuthlessApiError) {
    console.error("AUTHLESS_REQUEST_FAILED", {
      status: error.status,
      code: error.code,
      correlationId: error.correlationId,
      retrySafety: error.retrySafety,
    });
  }
  throw error;
}
